<template>
  <view class="page">
    <GlobalNavBar :title="board?.title||'留言板'"><template #left><view class="back-btn" @tap="back"><view></view></view></template><template #right><view class="more" @tap="actions">•••</view></template></GlobalNavBar>
    <scroll-view scroll-y class="scroll" :style="{paddingTop:topOffset+'px'}">
      <view v-if="board" class="content"><view class="board-head"><view class="board-mark">留</view><view><text>{{board.title}}</text><text>{{board.location.address}} · {{board.itemCount}} 条内容</text></view></view><text v-if="board.description" class="description">{{board.description}}</text>
        <view v-for="item in board.items" :key="item.id" class="note"><view class="note-meta"><view class="avatar">MQ</view><view><text>{{item.author.name}}</text><text>{{formatTime(item.createdAt)}}</text></view></view><text v-if="item.text" class="note-text">{{item.text}}</text><view v-if="item.images.length" class="images" :class="'count-'+Math.min(item.images.length,3)"><image v-for="(url,index) in item.images" :key="url" :src="url" mode="aspectFill" @tap="preview(item.images,index)"/></view><video v-if="item.video" class="video" :src="item.video.url" :poster="item.video.poster" controls/><view class="note-actions"><view @tap="like(item)"><view class="heart"></view><text>{{item.likes||'喜欢'}}</text></view><view @tap="reply(item)"><view class="bubble"></view><text>{{item.replies.length||'回复'}}</text></view></view><view v-if="item.replies.length" class="replies"><text v-for="reply in item.replies" :key="reply.id"><text>{{reply.author}}：</text>{{reply.text}}</text></view></view>
        <view class="ar"><view>AR</view><view><text>到店 AR 查看</text><text>空间锚定能力将在后续版本开放</text></view><text>暂未开放</text></view><view class="bottom-space"></view>
      </view><view v-else class="empty"><text>留言板不存在或已被删除</text><view @tap="back">返回地图</view></view>
    </scroll-view><view v-if="board" class="footer"><view @tap="back">查看地图</view><view @tap="add">继续留言</view></view>
  </view>
</template>
<script setup>
import { ref } from 'vue';import { onLoad } from '@dcloudio/uni-app';import GlobalNavBar from '../../components/common/GlobalNavBar.vue';import { messageBoardApi } from '../../utils/api/messageBoard.js'
const board=ref(null),topOffset=ref(68),id=ref('');function reload(){board.value=messageBoardApi.get(id.value)}onLoad(o=>{id.value=o.id||'';topOffset.value=uni.getStorageSync('TOP_NAV_METRICS')?.totalPx||68;reload()});function back(){uni.navigateBack()}function add(){uni.navigateTo({url:`/pages/message-board-editor/index?id=${encodeURIComponent(id.value)}`})}function like(item){try{board.value=messageBoardApi.toggleLike(id.value,item.id)}catch(e){uni.showToast({title:e.message,icon:'none'})}}function reply(item){uni.showModal({title:'回复留言',editable:true,placeholderText:'友善交流，分享你的想法',success:r=>{if(r.confirm&&r.content?.trim()){try{board.value=messageBoardApi.addReply(id.value,item.id,r.content)}catch(e){uni.showToast({title:e.message,icon:'none'})}}}})}function preview(images,index){uni.previewImage({urls:images,current:images[index]})}function formatTime(v){const d=new Date(v);return `${d.getMonth()+1}月${d.getDate()}日 ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}function actions(){uni.showActionSheet({itemList:['分享留言板','删除留言板'],success:r=>{if(r.tapIndex===0)return uni.showShareMenu?.();const removed=messageBoardApi.remove(id.value);board.value=null;uni.showToast({title:'已删除，可撤销',icon:'none'});setTimeout(()=>{if(!board.value&&removed){uni.showModal({title:'撤销删除？',content:'恢复刚刚删除的留言板',success:x=>{if(x.confirm){messageBoardApi.restore(removed);reload()}}})}},600)}})}
</script>
<style scoped>
.page{min-height:100vh;background:var(--color-page)}.scroll{height:100vh;box-sizing:border-box}.back-btn,.more{width:44px;height:44px;border-radius:15px;display:flex;align-items:center;justify-content:center;background:var(--color-surface-muted);color:#35403d;font-weight:800}.back-btn view{width:10px;height:10px;border-left:2px solid var(--color-text);border-bottom:2px solid var(--color-text);transform:rotate(45deg)}.content{padding:16px 14px}.board-head{display:flex;align-items:center;gap:12px;padding:4px 2px 16px}.board-mark{width:58px;height:58px;border-radius:18px;display:flex;align-items:center;justify-content:center;background:var(--color-text);color:#71e0d2;font-size:22px;font-weight:850}.board-head text{display:block}.board-head>view:last-child text:first-child{font-size:22px;font-weight:850}.board-head>view:last-child text:last-child{margin-top:5px;color:#707b78;font-size:11px}.description{display:block;margin:-5px 2px 16px;color:var(--color-text-body);font-size:13px;line-height:1.6}.note{margin-bottom:12px;padding:16px;border-radius:16px;background:#fff;box-shadow:var(--shadow-card)}.note-meta{display:flex;align-items:center;gap:9px}.avatar{width:40px;height:40px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:var(--color-primary-soft);color:var(--color-primary);font-size:11px;font-weight:850}.note-meta text{display:block}.note-meta>view:last-child text:first-child{font-weight:750}.note-meta>view:last-child text:last-child{margin-top:3px;color:#8b9592;font-size:10px}.note-text{display:block;margin-top:13px;color:#28312f;font-size:15px;line-height:1.65;white-space:pre-wrap}.images{display:grid;gap:5px;margin-top:12px}.images.count-1{grid-template-columns:1fr}.images.count-2{grid-template-columns:1fr 1fr}.images.count-3{grid-template-columns:2fr 1fr}.images image{width:100%;height:150px;border-radius:12px}.count-1 image{height:260px}.count-3 image:first-child{height:305px}.video{width:100%;height:260px;margin-top:12px;border-radius:13px}.note-actions{display:flex;gap:24px;margin-top:14px;padding-top:12px;border-top:1px solid var(--color-surface-muted)}.note-actions>view{min-height:40px;display:flex;align-items:center;gap:7px;color:#687370;font-size:11px}.heart{width:15px;height:13px;border:2px solid currentColor;border-radius:8px 8px 5px 5px;transform:rotate(-45deg)}.bubble{width:17px;height:13px;border:2px solid currentColor;border-radius:6px}.replies{padding:9px 11px;border-radius:11px;background:#f2f5f3}.replies>text{display:block;margin:5px 0;color:var(--color-text-body);font-size:11px}.replies>text>text{color:var(--color-primary);font-weight:700}.ar{padding:14px;border-radius:16px;display:flex;align-items:center;gap:11px;background:#eceefd}.ar>view:first-child{width:44px;height:44px;border-radius:13px;display:flex;align-items:center;justify-content:center;background:#fff;color:#5965b3;font-weight:850}.ar>view:nth-child(2){flex:1}.ar text{display:block}.ar>view text:first-child{font-weight:750}.ar>view text:last-child{margin-top:3px;color:#7f88aa;font-size:10px}.ar>text{font-size:10px;color:#7f88aa}.bottom-space{height:90px}.footer{position:fixed;z-index:10;left:0;right:0;bottom:0;padding:10px 14px calc(10px + env(safe-area-inset-bottom));display:grid;grid-template-columns:1fr 1.5fr;gap:9px;background:rgba(255,255,255,.95);box-shadow:var(--shadow-sheet)}.footer view{height:50px;border-radius:15px;display:flex;align-items:center;justify-content:center;background:var(--color-surface-muted);color:#46514e;font-weight:750}.footer view:last-child{background:var(--gradient-primary);color:#fff}.empty{padding:160px 24px;text-align:center}.empty text{display:block;color:#697370}.empty view{width:130px;height:48px;margin:20px auto;border-radius:15px;display:flex;align-items:center;justify-content:center;background:var(--color-text);color:#fff}
</style>
